TLM.f("Sancti/06-15",{"officium":"Ss. Viti, Modesti atque Crescentiæ Martyrum","rule":["Evangelium non appropriatum","vide C3;","Gloria"],"fallback":"Commune/C3","from":{"Tractus":"Commune/C3"},"sections":{"Introitus":[{"k":"ref","la":"Ps 33:20-21"},{"k":"text","la":"Multæ tribulatiónes justórum, et de his ómnibus liberávit eos Dóminus: Dóminus custódit ómnia ossa eórum: unum ex his non conterétur."},{"k":"ref","la":"Ps 33:2"},{"k":"text","la":"Benedícam Dóminum in omni témpore: semper laus ejus in ore meo."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Multæ tribulatiónes justórum, et de his ómnibus liberávit eos Dóminus: Dóminus custódit ómnia ossa eórum: unum ex his non conterétur."}],"Oratio":[{"k":"text","la":"Da Ecclésiæ tuæ, quǽsumus, Dómine, sanctis Martýribus tuis Vito, Modésto atque Crescéntia intercedéntibus, supérbe non sápere, sed tibi plácita humilitáte profícere: ut, prava despíciens, quæcúmque recta sunt, libera exérceat caritáte."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 3:1-8"},{"k":"text","la":"Justorum ánimæ in manu Dei sunt, et non tanget illos torméntum mortis. Visi sunt oculis insipiéntium mori: et æstimála est afflíctio exitus illórum: et quod a nobis est iter, extermínium: illi autem sunt in pace. Et si coram homínibus torménta passi sunt, spes illórum immortalitáte plena est. In paucis vexáti, in multis bene disponéntur: quóniam Deus tentávit eos, et invenit illos dignos se. Tamquam aurum in fornáce probávit illos, et quasi holocáusti hóstiam accépit illos, et in témpore erit respéctus illorum. Fulgébunt justi, et tamquam scintíllæ in arundinéto discúrrent. Judicábunt natiónes, et dominabúntur pópulis, et regnábit Dóminus illórum in perpétuum."}],"Graduale":[{"k":"ref","la":"Ps 149:5; 149:1"},{"k":"text","la":"Exsultábunt Sancti in glória: lætabúntur in cubílibus suis."},{"k":"text","la":"Cantáte Dómino cánticum novum: laus ejus in ecclésia sanctórum.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 144:10-11"},{"k":"text","la":"Sancti tui, Dómine, benedícent te: glóriam regni tui dicent. Allelúja."}],"Tractus":[{"k":"ref","la":"Exod 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 15:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 10:16-20"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Qui vos audit, me audit: et qui vos spernit, me spernit. Qui autem me spernit, spernit eum, qui misit me. Revérsi sunt autem septuagínta duo cum gáudio, dicéntes: Dómine, étiam dæmónia subjiciúntur nobis in nómine tuo. Et ait illis: Vidébam sátanam sicut fulgur de cœlo cadéntem. Ecce, dedi vobis potestátem calcandi supra serpéntes et scorpiónes, et super omnem virtútem inimíci: et nihil vobis nocébit. Verúmtamen in hoc nolíte gaudére, quia spíritus vobis subjiciúntur: gaudéte autem, quod nómina vestra scripta sunt in cœlis."}],"Offertorium":[{"k":"ref","la":"Ps 67:36"},{"k":"text","la":"Mirábilis Deus in Sanctis suis: Deus Israël, ipse dabit virtútem et fortitúdinem plebi suæ: benedíctus Deus, allelúja."}],"Secreta":[{"k":"text","la":"Sicut glóriam divínæ poténtiæ múnera pro Sanctis obláta testántur: sic nobis efféctum, Dómine, tuæ salvatiónis impéndant."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Sap 3:1-2; 3:3"},{"k":"text","la":"Justórum ánimæ in manu Dei sunt, et non tanget illos torméntum malítiæ: visi sunt óculis insipiéntium mori: illi autem sunt in pace."}],"Postcommunio":[{"k":"text","la":"Repléti, Dómine, benedictióne sollémni: quǽsumus; ut, per intercessiónem sanctórum Mártyrum tuórum Viti, Modésti et Crescéntiæ, medicína sacraménti et corpóribus nostris prosit et méntibus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"2c4a4dbe7e345ed3":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, Gospodine, Crkvi svojoj da po zagovoru tvojih svetih mučenika Vida, Modesta i Krescencije ne misli oholo nego da napreduje u tebi ugodnoj poniznosti i da prezire zlo, a slobodno i s ljubavlju izvršuje što je pravo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Daj Crkvi svojoj, molimo. Gospodine, da po zagovoru svetih mučenika Tvojih Vida, Modesta i Krescencije ne misli oholo, nego da napreduje Tebi ugodnom smjernošću, te prezirući zlo u slo- ,bodi Tvoje ljubavi izvršuje, što je pravo, po G. n.","knRef":"Kniewald 1942, str. 598–599 (snimka 300) (OCR)"},"98fc258ca30ecc80":{"t":"Gospodine, kao što darovi prikazani na čast tvojih svetih potvrđuju slavu božanske moći. tako nek nam dadu učinak tvoga spasenja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Kao što žrtve, prikazane u čast Tvojih svetih, svjedoče slavu božanske moći, tako nam, Gospodine, dobavile i djelovanje Tvoga otkupljenja, po G. n.","knRef":"Kniewald 1942, str. 598–599 (snimka 300) (OCR)"},"28b907740b520594":{"t":"<i>Pomolimo se</i>.\nNasićeni, Gospodine, svečanim blagoslovom, molimo, da po zagovoru svetih tvojih mučenika Vida, Modesta i Krescencije otajstveni lijek bude na korist i našem tijelu i duši.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Napunjeni, Gospodine, milošću ovoga blagdana, molimo, da nam zagovorom svetih Tvojih mučenika Vida, Modesta i Krescencije okrepa ovog otajstva koristi i tijelu i duši, po G. n.","knRef":"Kniewald 1942, str. 598–599 (snimka 300) (OCR)"}}});
